<script setup lang="ts">
import {computed,ref,onBeforeUnmount,nextTick,useId,watch} from 'vue'
import {aggregate,allowed,scopeIds,statusLabel,simulate,fixture,stamp,validate} from './model'
import type {Action,Run,Node,Ack} from './model'
import './orchestration.css'
const uid=useId()
const props=defineProps<{data?:Run;control?:(action:Action,run:Run)=>Promise<Ack>;theme?:string}>()
const emit=defineEmits<{selection:[id:string|null];control:[action:Action,result:Ack]}>()
const sample=ref(fixture()),run=computed(()=>props.data??sample.value),selection=ref<string|null>(props.data?.nodes.find(n=>n.kind==='run')?.id??'run'),tab=ref('Trace'),filter=ref('all'),query=ref(''),focusedOnly=ref(false),zoom=ref(1),mode=ref('ready'),pending=ref<Action|null>(null),message=ref(''),controlError=ref(false),failNext=ref(false),listView=ref(false),localDark=ref(false)
const root=ref<HTMLElement|null>(null),lastSelection=ref<HTMLElement|null>(null),collapsed=ref<string[]>([])
let timer:ReturnType<typeof setTimeout>|undefined,epoch=0
onBeforeUnmount(()=>{++epoch;if(timer)clearTimeout(timer)})
const hierarchy=computed(()=>{const ordered:Node[]=[];const visit=(id:string|null)=>{for(const n of run.value.nodes.filter(x=>x.parent===id)){ordered.push(n);visit(n.id)}};if(!errors.value.length)visit(null);return ordered})
const selected=computed(()=>run.value.nodes.find(n=>n.id===selection.value)),phases=computed(()=>run.value.nodes.filter(n=>n.kind==='phase')),runNode=computed(()=>run.value.nodes.find(n=>n.kind==='run')??fixture().nodes[0]),errors=computed(()=>validate(run.value))
const selectedIds=computed(()=>scopeIds(run.value,selection.value)),visibleIds=computed(()=>focusedOnly.value?selectedIds.value:scopeIds(run.value,null)),usage=computed(()=>run.value.usage.filter(u=>visibleIds.value.has(u.subject))),totals=computed(()=>aggregate(usage.value)),selectedTotals=computed(()=>aggregate(run.value.usage.filter(u=>selectedIds.value.has(u.subject))))
const events=computed(()=>run.value.events.filter(e=>visibleIds.value.has(e.subject)&&(filter.value==='all'||e.kind===filter.value)&&(`${e.summary} ${e.kind} ${label(e.subject)}`).toLowerCase().includes(query.value.toLowerCase())))
const trace=computed(()=>run.value.nodes.filter(n=>visibleIds.value.has(n.id)))
watch(()=>run.value.id,()=>{++epoch;if(timer)clearTimeout(timer);pending.value=null;message.value='Run changed. No pending control acknowledged.'})
const byParent=(id:string)=>run.value.nodes.filter(n=>n.parent===id)
const label=(id:string)=>run.value.nodes.find(n=>n.id===id)?.label??id
const number=(n:number|null)=>n===null?'n/a':n.toLocaleString('en-US')
const money=(n:number|null)=>n===null?'n/a':`$${n.toFixed(2)}`
const total=(v:{value:number|null;missing:number},currency=false)=>v.value===null?'n/a · unknown':`${currency?money(v.value):number(v.value)}${v.missing?' known · partial':''}`
const duration=(n:Node)=>n.duration===null?'n/a':`${n.duration}s`
const nodeUsage=(id:string)=>aggregate(run.value.usage.filter(u=>scopeIds(run.value,id).has(u.subject)))
const offset=(n:Node)=>n.started&&run.value.started?Math.max(0,(Date.parse(n.started)-Date.parse(run.value.started))/1000):0
const nodeIcon=(n:Node)=>n.kind==='run'?'✳':n.kind==='agent'?'◈':n.kind==='phase'?'◇':'↳'
function select(n:Node,e?:MouseEvent){selection.value=n.id;lastSelection.value=e?.currentTarget as HTMLElement??null;emit('selection',n.id)}
function close(){selection.value=null;emit('selection',null);nextTick(()=>lastSelection.value?.focus())}
function toggle(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(x=>x!==id):[...collapsed.value,id]}
function changeTab(name:string){tab.value=name}
function tabKey(e:KeyboardEvent){const tabs=['Trace','Usage','Events'];let i=tabs.indexOf(tab.value);if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;tab.value=tabs[i];nextTick(()=>root.value?.querySelector<HTMLButtonElement>(`[role=tab][aria-selected=true]`)?.focus())}}
async function control(action:Action){
 if(props.data&&!props.control){controlError.value=true;message.value='No execution adapter connected. No control acknowledged.';return}
 if(pending.value||!run.value.capabilities[action]||!allowed(action,runNode.value.status))return
 pending.value=action;controlError.value=false;message.value=`${action==='pause'?'Finishing the current sample call':'Waiting for sample response'}...`;const token=++epoch,status=runNode.value.status
 let ack:Ack
 try {ack=props.control?await props.control(action,run.value):await new Promise<Ack>(resolve=>{timer=setTimeout(()=>resolve(simulate(action,status,failNext.value)),650)})}catch{ack={state:'error',message:'Adapter failed. No state change acknowledged.'}}
 if(token!==epoch)return
 pending.value=null;failNext.value=false;message.value=ack.message;controlError.value=ack.state==='error'
 if(ack.state==='ack'&&ack.status&&!props.data){sample.value={...sample.value,nodes:sample.value.nodes.map(n=>n.kind==='run'?{...n,status:ack.status!}:n),events:[...sample.value.events,{id:`control-${sample.value.events.length}`,ts:stamp(104+sample.value.events.length),kind:'status_change',subject:'run',summary:ack.message}]}}
 emit('control',action,ack)
}
function update(){if(props.data)return;sample.value={...sample.value,nodes:sample.value.nodes.map(n=>n.id==='retry'?{...n,duration:(n.duration??0)+1}:n),events:[...sample.value.events,{id:`update-${sample.value.events.length}`,ts:stamp(110+sample.value.events.length),kind:'note',subject:'retry',summary:'One deterministic sample update. Selection and scroll stay in place.'}]};message.value='Sample update applied. Selection and filters preserved.'}
function reset(){++epoch;if(timer)clearTimeout(timer);pending.value=null;sample.value=fixture();selection.value=props.data?.nodes.find(n=>n.kind==='run')?.id??'run';tab.value='Trace';filter.value='all';query.value='';focusedOnly.value=false;zoom.value=1;mode.value='ready';collapsed.value=[];listView.value=false;message.value='';controlError.value=false;failNext.value=false}
</script>
<template>
<section ref="root" class="orch" :class="[{ 'orch-local-dark':localDark},`orch-${theme??'inherit'}`]" aria-label="Agent orchestration simulation" @keydown.esc="close">
 <header class="orch-header"><div><span class="orch-eyebrow">AGENT ORCHESTRATION / SYNTHETIC RUN</span><h2>{{run.label}} <span class="orch-live">{{statusLabel[runNode.status]}}</span></h2><p>{{run.id}} · Presentation only. No agents or services connected.</p></div>
 <div class="orch-actions"><button v-for="a in (['pause','resume','stop','retry'] as Action[])" :key="a" v-show="run.capabilities[a]&&(allowed(a,runNode.status)||pending===a)" :disabled="!!pending||!!data&&!props.control" :title="a==='pause'?'Finish the current sample call, then wait.':`Simulate ${a}`" @click="control(a)">{{pending===a?'Pending...':a[0].toUpperCase()+a.slice(1)}}</button><button v-if="['meadow','sentinel','brief'].includes(theme??'')" @click="localDark=!localDark">{{localDark?'Light':'Dark'}} mode</button></div></header>
 <div class="orch-notice" :class="{'orch-error':controlError}" aria-live="polite">{{message||'Simulated data and controls. Dollar amounts are illustrative, not a bill.'}}</div>
 <div class="orch-demo-tools"><label>View state <select aria-label="View state" v-model="mode"><option value="ready">Ready</option><option>loading</option><option>empty</option><option>error</option></select></label><label v-if="!data"><input type="checkbox" v-model="failNext"/> Fail next control</label><button v-if="!data" @click="update">Apply sample update</button><button @click="reset">Reset example</button></div>
 <div v-if="mode!=='ready'||errors.length" class="orch-placeholder" role="status"><strong>{{errors.length?'Invalid adapter data':mode==='loading'?'Loading sample run':mode==='empty'?'No runs yet':'Could not load the sample run'}}</strong><p>{{errors.length?errors.join('; '):'Choose Ready to return to the deterministic example.'}}</p></div>
 <template v-else>
 <div class="orch-workspace" :class="{'orch-with-drawer':!!selected}"><div class="orch-main">
 <div class="orch-canvas-tools"><span>Run map <small>{{run.nodes.length}} nodes · {{phases.length}} phases</small></span><div><button :aria-pressed="listView" @click="listView=!listView">{{listView?'Graph view':'List view'}}</button><button aria-label="Zoom out" :disabled="zoom<=.7" @click="zoom=Math.max(.7,zoom-.1)">−</button><span>{{Math.round(zoom*100)}}%</span><button aria-label="Zoom in" :disabled="zoom>=1.4" @click="zoom=Math.min(1.4,zoom+.1)">+</button><button @click="zoom=1">Reset zoom</button></div></div>
 <div v-show="!listView" class="orch-canvas" tabindex="0" aria-label="Scrollable run graph. Use List view for an equivalent hierarchy."><div class="orch-map" :style="{zoom}">
 <div class="orch-root"><button class="orch-node" :class="{selected:selection===runNode.id}" @click="select(runNode,$event)"><span class="orch-node-kind">✳ ORCHESTRATOR</span><strong>{{run.label}}</strong><span :class="`orch-status ${runNode.status}`">{{statusLabel[runNode.status]}}</span><small>{{duration(runNode)}} · {{total(aggregate(run.usage).cost,true)}}</small></button></div>
 <div class="orch-branches"><section v-for="phase in phases" :key="phase.id" class="orch-lane"><button class="orch-phase" :class="{selected:selection===phase.id}" @click="select(phase,$event)">{{phase.label}} <span>{{statusLabel[phase.status]}}</span></button><button class="orch-collapse" :aria-expanded="!collapsed.includes(phase.id)" @click="toggle(phase.id)">{{collapsed.includes(phase.id)?'Expand phase':'Collapse phase'}}</button><div v-if="!collapsed.includes(phase.id)"><div v-for="agent in byParent(phase.id)" :key="agent.id" class="orch-agent"><button class="orch-node" :class="{selected:selection===agent.id}" @click="select(agent,$event)"><span class="orch-node-kind">◈ AGENT · {{agent.model??'n/a'}}</span><strong>{{agent.label}}</strong><span :class="`orch-status ${agent.status}`">{{statusLabel[agent.status]}}</span><small>{{duration(agent)}} · {{total(nodeUsage(agent.id).cost,true)}}</small></button><button v-for="task in byParent(agent.id)" :key="task.id" class="orch-node orch-task" :class="{selected:selection===task.id}" @click="select(task,$event)"><span class="orch-node-kind">↳ TASK</span><strong>{{task.label}}</strong><span :class="`orch-status ${task.status}`">{{statusLabel[task.status]}}</span><small>{{duration(task)}} · {{total(nodeUsage(task.id).cost,true)}}</small></button></div></div></section></div>
 </div></div>
 <div class="orch-hierarchy" :class="{'orch-list-visible':listView}" aria-label="Equivalent run hierarchy"><p>Keyboard and compact hierarchy. Select any item for details.</p><ul><li v-for="n in hierarchy" :key="n.id" :style="{paddingInlineStart:({run:0,phase:12,agent:24,task:36}[n.kind])+'px'}"><button :class="{selected:selection===n.id}" @click="select(n,$event)"><span>{{nodeIcon(n)}} {{n.label}} <small>{{n.kind}}</small></span><span :class="`orch-status ${n.status}`">{{statusLabel[n.status]}}</span></button></li></ul></div>
 <div class="orch-summary"><span>{{run.nodes.filter(n=>n.kind==='task'&&n.status==='succeeded').length}} / {{run.nodes.filter(n=>n.kind==='task').length}} tasks done</span><span>{{duration(runNode)}} elapsed</span><strong>{{total(aggregate(run.usage).cost,true)}} USD</strong></div>
 </div>
 <aside v-if="selected" class="orch-drawer" aria-label="Selected node details"><div class="orch-drawer-top"><small>{{selected.kind.toUpperCase()}}</small><button aria-label="Close node details" @click="close">×</button></div><h3>{{selected.label}}</h3><span :class="`orch-status ${selected.status}`">{{statusLabel[selected.status]}}</span><dl><dt>Node ID</dt><dd>{{selected.id}}</dd><dt>Parent</dt><dd>{{selected.parent?label(selected.parent):'Root'}}</dd><dt>Model</dt><dd>{{selected.model??'n/a'}}</dd><dt>Started (UTC)</dt><dd>{{selected.started??'Not started'}}</dd><dt>Ended (UTC)</dt><dd>{{selected.ended??'Not ended'}}</dd><dt>Duration</dt><dd>{{duration(selected)}}</dd><dt>Cost (USD)</dt><dd>{{total(selectedTotals.cost,true)}}</dd><dt>Input / output</dt><dd>{{total(selectedTotals.input)}} / {{total(selectedTotals.output)}}</dd></dl><p v-if="selected.error" class="orch-error">{{selected.error}}</p><p v-if="selected.status==='needs_input'">Waiting for sample input. Approve and deny are not connected.</p><div class="orch-drawer-links"><button @click="focusedOnly=true;changeTab('Events')">Related events</button><button @click="focusedOnly=true;changeTab('Usage')">Related usage</button></div><div class="orch-relations"><small>Connections</small><p v-for="e in run.edges.filter(e=>e.from===selected!.id||e.to===selected!.id)" :key="e.from+e.to">{{e.kind}}: {{label(e.from)}} → {{label(e.to)}}</p></div></aside></div>
 <div class="orch-tabs" role="tablist" aria-label="Run observations" @keydown="tabKey"><button v-for="t in ['Trace','Usage','Events']" :id="`${uid}-tab-${t}`" :key="t" role="tab" :aria-selected="tab===t" :tabindex="tab===t?0:-1" :aria-controls="`${uid}-panel-${t}`" @click="changeTab(t)">{{t==='Usage'?'Tokens & cost':t}}</button></div>
 <div class="orch-filter"><label><input type="checkbox" v-model="focusedOnly" :disabled="!selection"/> Selected node and descendants</label><button @click="focusedOnly=false;filter='all';query=''">Clear filters</button></div>
 <div v-show="tab==='Trace'" :id="`${uid}-panel-Trace`" class="orch-panel" role="tabpanel" :aria-labelledby="`${uid}-tab-Trace`"><p class="orch-help">Elapsed seconds from run start · static sample, no auto-follow</p><div class="orch-trace-scroll" tabindex="0" aria-label="Horizontally scrollable trace"><div class="orch-trace"><div class="orch-trace-scale"><span>Agent / task</span><div><span v-for="s in [0,20,40,60,80,100,120]" :key="s">{{s}}s</span></div></div><div v-for="n in trace" :key="n.id" class="orch-trace-row" :class="{highlight:selection===n.id}"><button @click="select(n,$event)">{{nodeIcon(n)}} {{n.label}}</button><div class="orch-track"><button v-if="n.started&&n.duration!==null" class="orch-bar" :class="n.status" :style="{left:(offset(n)/120*100)+'%',width:Math.max(2,(n.duration??0)/120*100)+'%'}" :aria-label="`${n.label}: ${statusLabel[n.status]}, ${duration(n)}`" @click="select(n,$event)"></button><span v-else class="orch-not-started">{{n.started?'Duration unknown':'Not started'}}</span></div><span>{{duration(n)}}</span></div></div></div></div>
 <div v-show="tab==='Usage'" :id="`${uid}-panel-Usage`" class="orch-panel" role="tabpanel" :aria-labelledby="`${uid}-tab-Usage`"><p class="orch-help">Exclusive task usage only. Parent summaries are not added again. n/a means unknown, not zero. Cache tokens are a subset of input, not added to input.</p><div class="orch-table-scroll" tabindex="0" aria-label="Scrollable sample usage table"><table><thead><tr><th>Agent / task · model</th><th>Input</th><th>Output</th><th>Cache</th><th>Cost USD</th></tr></thead><tbody><tr v-for="u in usage" :key="u.id"><td><button @click="selection=u.subject">{{label(u.subject)}}</button><small>{{u.model??'n/a'}} · {{u.basis}}</small></td><td>{{number(u.input)}}</td><td>{{number(u.output)}}</td><td>{{number(u.cache)}}</td><td>{{money(u.cost)}}</td></tr></tbody><tfoot><tr><th>Known total ({{totals.cost.missing}} unknown)</th><td>{{total(totals.input)}}</td><td>{{total(totals.output)}}</td><td>{{total(totals.cache)}}</td><td>{{total(totals.cost,true)}}</td></tr></tfoot></table></div></div>
 <div v-show="tab==='Events'" :id="`${uid}-panel-Events`" class="orch-panel" role="tabpanel" :aria-labelledby="`${uid}-tab-Events`"><div class="orch-event-tools"><label>Event type <select v-model="filter"><option value="all">All events</option><option v-for="k in ['tool_call','handoff','approval','error','status_change','note']" :key="k">{{k}}</option></select></label><label>Search events <input type="search" v-model="query" placeholder="Search sample log"/></label></div><ol class="orch-events"><li v-for="e in events" :key="e.id"><time>{{e.ts.slice(11,19)}} UTC</time><span>{{e.kind.replace('_',' ')}}</span><div><button @click="selection=e.subject">{{label(e.subject)}}</button><p>{{e.summary}}</p></div></li></ol><p v-if="!events.length">No events match these filters.</p></div>
 </template>
</section>
</template>
